-- Disposable localhost PostgreSQL ONLY. No shared/hosted Supabase.
\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'ASSERT: %',message;end if;end $$;
create function pg_temp.reject(sql text,expected text) returns void language plpgsql as $$begin begin execute sql;exception when others then if sqlstate=expected then return;end if;raise;end;raise exception 'Expected rejection: %',sql;end $$;
select pg_temp.assert(private.reminder_instant('2026-10-21',null,'day')='2026-10-20 13:00Z','date only 9am');
select pg_temp.assert(private.reminder_instant('2026-11-01','01:30','three_hours')='2026-11-01 03:30Z','fold uses later standard time');
select pg_temp.assert(private.reminder_instant('2026-03-08','02:30','three_hours')='2026-03-08 04:30Z','spring gap advances');
select pg_temp.assert(private.reminder_instant('2028-03-01',null,'day')='2028-02-29 14:00Z','leap day');
select pg_temp.assert(private.reminder_instant('2027-01-01',null,'week')='2026-12-25 14:00Z','year boundary');
insert into auth.users(id,email,email_confirmed_at) values('c0000000-0000-0000-0000-000000000001','reminders-a@stonybrook.edu',now()),('c0000000-0000-0000-0000-000000000002','reminders-b@stonybrook.edu',now()),('c0000000-0000-0000-0000-000000000003','reminders-c@example.com',now());
insert into auth.identities select id,'google',jsonb_build_object('email',email,'email_verified',true) from auth.users where id::text like 'c0000000-%';
insert into public.user_courses(id,user_id,course_code) values('c1000000-0000-0000-0000-000000000001','c0000000-0000-0000-0000-000000000001','CSE 416'),('c1000000-0000-0000-0000-000000000002','c0000000-0000-0000-0000-000000000002','CSE 416');
set local role authenticated;
select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000001',true);
select pg_temp.assert(public.academic_reminder_settings()->'exam'='["week","day"]','exam defaults');
insert into public.academic_items(id,user_course_id,title,type,due_date,due_time) values('c2000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Exam','exam',current_date+10,'17:00');
select pg_temp.assert((select count(*)=2 from public.academic_reminder_occurrences),'two future thresholds');
select pg_temp.reject($q$update public.academic_items set reminder_revision=999$q$,'42501');
select pg_temp.reject($q$update public.academic_reminder_occurrences set state='delivered'$q$,'42501');
select pg_temp.reject($q$update public.academic_items set reminder_offsets=array['day','day']$q$,'23514');
select pg_temp.reject($q$update public.academic_items set reminder_offsets=array['invalid']$q$,'23514');
update public.academic_items set reminder_offsets=array['three_hours'];
select pg_temp.reject($q$update public.academic_items set due_time=null$q$,'23514');
update public.academic_items set reminder_offsets=null;
reset role;
-- Advance only synthetic occurrence timestamps, not production clock/functions.
update public.academic_reminder_occurrences set due_at=clock_timestamp()-case offset_key when 'week' then interval '2 hours' else interval '1 hour' end where item_id='c2000000-0000-0000-0000-000000000001' and state='scheduled';
set local role authenticated;
select public.academic_reminders_refresh();select public.academic_reminders_refresh();
select pg_temp.assert(public.academic_reminders_list()->>'unread'='1','catchup delivers most recent only once');
select set_config('test.reminder_id',public.academic_reminders_list()->'rows'->0->>'id',true);
select public.academic_reminder_read(current_setting('test.reminder_id')::uuid);
select pg_temp.assert(public.academic_reminders_list()->>'unread'='0' and jsonb_array_length(public.academic_reminders_list()->'rows')=1,'read retains row');
select public.academic_reminder_clear(current_setting('test.reminder_id')::uuid);select public.academic_reminder_clear(current_setting('test.reminder_id')::uuid);
select public.academic_reminders_refresh();select pg_temp.assert(public.academic_reminders_list()->'rows'='[]','clear remains terminal');
update public.academic_items set title='Renamed';select public.academic_reminders_refresh();select pg_temp.assert(public.academic_reminders_list()->'rows'='[]','title change no replay');
select public.academic_reminder_settings_save('{"enabled":false,"assignment":["day"],"exam":["week","day"],"quiz":["day"],"project":["week","day"]}');
select pg_temp.assert(public.academic_reminder_settings()->>'enabled'='false','disabled persisted');
select public.academic_reminder_settings_save('{"enabled":true,"assignment":["day"],"exam":["three_days"],"quiz":[],"project":["week","day"]}');
select pg_temp.assert((select count(*)=1 from public.academic_reminder_occurrences where state='scheduled'),'new future default threshold');
update public.academic_items set completed_at=now();select pg_temp.assert((select count(*)=0 from public.academic_reminder_occurrences where state in('scheduled','delivered')),'completion cancels active');
update public.academic_items set completed_at=null;select pg_temp.assert((select count(*)=1 from public.academic_reminder_occurrences where state='scheduled'),'reopen future cancelled schedule');
update public.academic_items set due_date=due_date+1;select pg_temp.assert((select reminder_revision=2 from public.academic_items),'deadline increments revision');
select pg_temp.assert((select count(*)=0 from public.academic_reminder_occurrences where revision=1 and state in('scheduled','delivered')),'old revision invalidated');
-- Late creation does not backfill; a due occurrence whose item became overdue is skipped.
insert into public.academic_items(id,user_course_id,title,type,due_date,reminder_offsets) values('c5000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Already due','assignment',current_date-1,array['day']);
select pg_temp.assert((select state='skipped' from public.academic_reminder_occurrences where item_id='c5000000-0000-0000-0000-000000000001'),'past threshold skipped on create');
reset role;
update public.academic_reminder_occurrences set state='scheduled',due_at=clock_timestamp()-interval '1 hour' where item_id='c5000000-0000-0000-0000-000000000001';
set local role authenticated;select public.academic_reminders_refresh();
select pg_temp.assert((select state='skipped' from public.academic_reminder_occurrences where item_id='c5000000-0000-0000-0000-000000000001'),'overdue catchup skipped');
delete from public.academic_items where id='c5000000-0000-0000-0000-000000000001';
-- More notifications than one page; unrelated late arrival must survive bounded clear.
insert into public.academic_items(id,user_course_id,title,type,due_date,due_time,reminder_offsets)
select ('c3000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'c1000000-0000-0000-0000-000000000001','Assignment '||n,'assignment',current_date+5,'17:00',array['day'] from generate_series(1,25)n;
reset role;
update public.academic_reminder_occurrences set due_at=clock_timestamp()-interval '1 minute' where state='scheduled';
set local role authenticated;
select public.academic_reminders_refresh();select pg_temp.assert(jsonb_array_length(public.academic_reminders_list()->'rows')=20,'page bounded');
select pg_temp.assert((public.academic_reminders_list()->>'unread')::int=26,'full count across pages');
select set_config('test.cursor',(public.academic_reminders_list()->'rows'->19)::text,true);
select pg_temp.assert(jsonb_array_length(public.academic_reminders_list((current_setting('test.cursor')::jsonb->>'delivered_at')::timestamptz,(current_setting('test.cursor')::jsonb->>'id')::uuid)->'rows')=6,'remaining page');
select set_config('test.bound',public.academic_reminders_bound()::text,true);
insert into public.academic_items(id,user_course_id,title,type,due_date,reminder_offsets) values('c4000000-0000-0000-0000-000000000001','c1000000-0000-0000-0000-000000000001','Later','assignment',current_date+4,array['day']);
reset role;update public.academic_reminder_occurrences set due_at=clock_timestamp()-interval '1 minute' where item_id='c4000000-0000-0000-0000-000000000001';set local role authenticated;
select public.academic_reminders_refresh();select public.academic_reminders_clear_all(current_setting('test.bound')::bigint);select public.academic_reminders_clear_all(current_setting('test.bound')::bigint);
select pg_temp.assert(public.academic_reminders_list()->>'unread'='1','late arrival survives clear all');
select set_config('test.peer_id',public.academic_reminders_list()->'rows'->0->>'id',true);
select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000002',true);
select pg_temp.assert((select count(*)=0 from public.academic_reminder_occurrences),'peer cannot select');
select pg_temp.assert(public.academic_reminders_list()->'rows'='[]','peer has own empty inbox');
select pg_temp.reject('select public.academic_reminder_read('''||current_setting('test.peer_id')||''')','42501');
select pg_temp.reject('select public.academic_reminder_clear('''||current_setting('test.peer_id')||''')','42501');
select pg_temp.reject('select public.academic_reminders_list('''||(current_setting('test.cursor')::jsonb->>'delivered_at')||''','''||(current_setting('test.cursor')::jsonb->>'id')||''')','22023');
select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000003',true);
select pg_temp.reject('select public.academic_reminders_refresh()','42501');
set local role anon;select pg_temp.reject('select public.academic_reminders_refresh()','42501');
set local role authenticated;select set_config('request.jwt.claim.sub','c0000000-0000-0000-0000-000000000001',true);
delete from public.academic_items where id='c4000000-0000-0000-0000-000000000001';
select pg_temp.assert(public.academic_reminders_list()->'rows'='[]','source delete clears reminder without harming siblings');
select pg_temp.assert((select count(*)=26 from public.academic_items),'siblings retained');
rollback;
